package ui;

import assessment.TesterLoader;
import config.Config;
import generation.QuestionGenerationOutcome;
import generation.QuestionGenerationOutcome.GenerationStatus;
import generation.QuestionSpec;
import generation.progress.GenerationProgress;
import grading.progress.GradingProgress;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Map;
import java.util.concurrent.CancellationException;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.FutureTask;

// Generated by ChatGPT-6-Astra, Modified to include menu operations
// Owns one menu session and prevents operations from overlapping during cancellation.
final public class UiSession implements AutoCloseable {
    enum Screen { 
        menu, 
        generating, 
        grading 
    }

    private static final UIOperations DEFAULT = new UiActiveOperations();

    private final Config config;
    private final UIOperations operations;
    private Path activeTesters;
    private FutureTask<Path> task;
    private Thread worker;
    private boolean settled = true, cancelling;
    private Screen screen = Screen.menu;
    private String notice = "configuration checked > choose an operation";
    private GradingProgress grading;
    private GenerationProgress generation;

    public UiSession(Config config) { this(config, DEFAULT); }
    public UiSession(Config config, UIOperations operations) {
        this.config = config;
        this.operations = operations;
        activeTesters = config.getTestersDirectory();
    }

    Config config() { return config; }
    Path activeTesters() { return activeTesters; }
    Screen screen() { return screen; }
    String notice() { return notice; }
    boolean settled() { return settled; }
    boolean cancelling() { return cancelling; }
    GradingProgress grading() { return grading; }
    GenerationProgress generation() { return generation; }

    void start(Screen operation) {
        if (screen != Screen.menu || !settled || operation == Screen.menu)
            throw new IllegalStateException("return to the menu before starting another operation");

        screen = operation;
        settled = false;
        cancelling = false;
        // Fresh trackers and tasks keep counts and elapsed time separate for every run.
        grading = new GradingProgress();
        generation = new GenerationProgress();
        
        task = new FutureTask<>(() -> {
            if (operation == Screen.grading) {
                operations.grade(config.withOverrides(Map.of("testers.folder", activeTesters.toString())), grading);
                return null;
            }
            // Preserve earlier successful testers even if this generation fails or is cancelled.
            Path root = Files.createDirectories(config.getGenerationOutputDirectory());
            Path output = Files.createTempDirectory(root, "run-");
            Config runConfig = config.withOverrides(Map.of("generation.files.dir", output.toString()));
            var outcomes = operations.generate(runConfig, generation);
            var expected = QuestionSpec.collect(config.getResourcesDirectory()).stream()
                    .map(QuestionSpec::id).collect(java.util.stream.Collectors.toSet());
            var written = outcomes.stream().filter(result -> result.status() == GenerationStatus.written)
                    .map(QuestionGenerationOutcome::questionId).collect(java.util.stream.Collectors.toSet());
            if (outcomes.size() != expected.size() || expected.isEmpty() || !written.equals(expected))
                throw new IllegalStateException("generation incomplete > previous tester source retained");
            // Verify the saved set can actually be loaded before making it active.
            var loaded = TesterLoader.load(output);
            if (expected.stream().anyMatch(id -> !loaded.containsKey(id.toLowerCase(java.util.Locale.ROOT))))
                throw new IllegalStateException("generated tester set is incomplete");
            return output;
        });

        worker = new Thread(task, "ui-" + operation);
        worker.start();
    }

    // Future cancellation may finish before the worker does; wait for actual cleanup before returning.
    void cancel() {
        if (!settled) {
            cancelling = true;
            task.cancel(true);
        }
    }

    void poll() {
        if (settled || worker.isAlive()) return;
        boolean failed = false;
        try {
            Path generated = task.get();
            if (generated != null) activeTesters = generated;
            notice = screen == Screen.generating ? "testers generated > selected for grading" : "grading finished > scoresheet saved";
        } catch (CancellationException error) {
            failed = true;
            notice = "operation cancelled > cleanup finished";
        } catch (ExecutionException error) {
            failed = true;
            Throwable cause = error.getCause();
            notice = cause.getMessage() == null ? cause.toString() : cause.getMessage();
        } catch (InterruptedException error) {
            Thread.currentThread().interrupt();
            return;
        }
        if (screen == Screen.generating) generation.finish(notice, failed);
        else {
            if (failed) grading.failed(notice);
            grading.finishElapsedTime();
        }
        settled = true;
    }

    void menu() {
        poll();
        if (!settled) throw new IllegalStateException("worker is still cleaning up");
        screen = Screen.menu;
    }

    @Override public void close() {
        cancel();
        boolean interrupted = false;
        while (worker != null && worker.isAlive()) {
            try { worker.join(); }
            catch (InterruptedException error) { interrupted = true; cancel(); }
        }
        if (interrupted) Thread.currentThread().interrupt();
    }
}
